function processArray(arr, callback) {
  const results = [];
  for (let i = 0; i < arr.length; i++) {
    const processed = callback(arr[i], i);
    results.push(processed);
  }
  return results;
}

function double(value, index) {
  return value * 2;
}

function addIndex(value, index) {
  return value + index;
}

const numbers = [1, 2, 3];
const doubled = processArray(numbers, double);
const indexed = processArray(numbers, addIndex);

console.log(doubled);
console.log(indexed);

